contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test: make a deposit (possibly zero) and assert the account balance increased by >= the sent value
    function testPutKeepsDeposit(uint unlockTime, uint amount) public payable {
        // require this contract has enough balance to forward 'amount'
        require(address(this).balance >= amount);

        // read previous balance for this test contract's address in c
        uint before = c.Acc(address(this)).balance;

        // call Put with provided amount forwarded
        c.Put{value: amount}(unlockTime);

        // read after balance
        uint after = c.Acc(address(this)).balance;

        // The invariant: after - before >= amount (i.e., the deposit was recorded).
        // This holds in the original P even when amount == 0, but the mutant rejects amount==0 causing the assertion to be violated for amount==0.
        assert(after - before >= amount);
    }

    // allow funding this test contract externally
    receive() external payable {}
}

