import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: depositor address, deposit amount (>= MinSum), unlockTime offset, collect amount
    function testFuzz_property(address depositor, uint256 depositAmount, uint256 unlockOffset, uint256 collectAmount) public {
        // keep values in wide but admissible ranges
        vm.assume(depositor != address(0));
        // MinSum is 1 ether in contract; ensure depositAmount >= MinSum to allow Collect path
        uint256 minSum = 1 ether;
        depositAmount = depositAmount < minSum ? minSum : depositAmount;
        // bound amounts to reasonable values to avoid overflows in test harness
        depositAmount = bound(depositAmount, minSum, 100 ether);
        collectAmount = bound(collectAmount, 0, depositAmount);
        // set unlockTime in the past or future depending on fuzzed offset
        uint256 nowt = block.timestamp;
        uint256 unlockTime = nowt + (unlockOffset % 1000);

        // fund depositor
        vm.deal(depositor, depositAmount);

        // depositor makes a payable Put deposit
        vm.prank(depositor);
        c.Put{value: depositAmount}(unlockTime);

        // advance time past unlockTime to enable Collect when possible
        vm.warp(unlockTime + 1);

        // depositor calls Collect for collectAmount (<= balance)
        vm.prank(depositor);
        bool collectSucceeded;
        try c.Collect(collectAmount) {
            collectSucceeded = true;
        } catch {
            collectSucceeded = false;
        }

        // Now: attempt a zero-value Put call (this is allowed by reference but blocked by mutant)
        vm.prank(depositor);
        bool zeroPutSucceeded;
        try c.Put(0) {
            zeroPutSucceeded = true;
        } catch {
            zeroPutSucceeded = false;
        }

        // Assertion: On the reference implementation, zero-value Put always succeeds (returns/doesn't revert).
        // This is the single assertTrue required: it reads c via the behavior of calling c.Put(0).
        // The mutant that added `require(msg.value > 0)` will make zeroPutSucceeded == false for some inputs,
        // causing this test to fail on the mutant while passing on the reference for all inputs.
        assertTrue(zeroPutSucceeded);
    }
}

